class Solution {
public:
    int minIncrements(vector<int>& nums, vector<int>& target) {
        int t = target.size(), full = (1 << t) - 1;
        const long long INF = LLONG_MAX / 2;
        vector<long long> dp(full + 1, INF), ndp(full + 1);
        dp[0] = 0;
        for (int a : nums) {
            ndp = dp;
            for (int mask = 0; mask <= full; mask++) {
                if (dp[mask] >= INF) continue;
                int free = full ^ mask;
                for (int S = free; ; S = (S - 1) & free) {
                    long long L = 1;
                    for (int i = 0; i < t; i++) if (S >> i & 1) L = L / __gcd(L, (long long)target[i]) * target[i];
                    long long c = (a + L - 1) / L * L - a;
                    int nm = mask | S;
                    ndp[nm] = min(ndp[nm], dp[mask] + c);
                    if (S == 0) break;
                }
            }
            dp = ndp;
        }
        return (int) dp[full];
    }
};

