class Solution {
    public int minIncrements(int[] nums, int[] target) {
        int t = target.length, full = (1 << t) - 1;
        long INF = Long.MAX_VALUE / 2;
        long[] dp = new long[full + 1], ndp = new long[full + 1];
        Arrays.fill(dp, INF); dp[0] = 0;
        for (int a : nums) {
            ndp = dp.clone();
            for (int mask = 0; mask <= full; mask++) {
                if (dp[mask] >= INF) continue;
                int free = full ^ mask;
                for (int S = free; ; S = (S - 1) & free) {
                    long L = 1;
                    for (int i = 0; i < t; i++) if (((S >> i) & 1) == 1) L = L / gcd(L, target[i]) * target[i];
                    long c = (a + L - 1) / L * L - a;
                    ndp[mask | S] = Math.min(ndp[mask | S], dp[mask] + c);
                    if (S == 0) break;
                }
            }
            dp = ndp;
        }
        return (int) dp[full];
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
}

