var minIncrements = function(nums, target) {
    const t = target.length, full = (1 << t) - 1;
    const INF = Infinity;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    let dp = new Array(full + 1).fill(INF); dp[0] = 0;
    for (const a of nums) {
        const ndp = dp.slice();
        for (let mask = 0; mask <= full; mask++) {
            if (dp[mask] === INF) continue;
            const free = full ^ mask;
            for (let S = free; ; S = (S - 1) & free) {
                let L = 1;
                for (let i = 0; i < t; i++) if ((S >> i) & 1) L = L / gcd(L, target[i]) * target[i];
                const c = Math.ceil(a / L) * L - a;
                const nm = mask | S;
                if (dp[mask] + c < ndp[nm]) ndp[nm] = dp[mask] + c;
                if (S === 0) break;
            }
        }
        dp = ndp;
    }
    return dp[full];
};
